import type { INodeProperties } from 'n8n-workflow';
import { idField, paymentSourceOptions, returnAllAndLimit, toCalendarDate } from '../shared/descriptions';

const R = 'upcomingBill';
const show = (operation: string[]) => ({ show: { resource: [R], operation } });

/**
 * Upcoming bills are generated by Cashly from EMIs, subscriptions, credit
 * card due days and debt due dates. They can be listed, paid or skipped.
 */
export const billDescription: INodeProperties[] = [
	{
		displayName: 'Operation',
		name: 'operation',
		type: 'options',
		noDataExpression: true,
		displayOptions: { show: { resource: [R] } },
		options: [
			{
				name: 'Get Many',
				value: 'getAll',
				action: 'Get many upcoming bills',
				description: 'List bills due from EMIs, subscriptions, credit cards and debts',
				routing: {
					request: { method: 'GET', url: '/upcoming-bills' },
					output: { postReceive: [{ type: 'rootProperty', properties: { property: 'bills' } }] },
				},
			},
			{
				name: 'Record Payment',
				value: 'recordPayment',
				action: 'Pay an upcoming bill',
				description: 'Mark a bill as paid and record the transaction',
				routing: { request: { method: 'POST', url: '=/upcoming-bills/{{$parameter.billId}}/pay' } },
			},
			{
				name: 'Skip',
				value: 'skip',
				action: 'Skip an upcoming bill',
				description: 'Skip this occurrence without recording a payment',
				routing: { request: { method: 'POST', url: '=/upcoming-bills/{{$parameter.billId}}/skip' } },
			},
		],
		default: 'getAll',
	},

	idField('Bill ID', 'billId', R, ['recordPayment', 'skip'], 'The ID of the upcoming bill'),

	{
		displayName: 'Options',
		name: 'paymentOptions',
		type: 'collection',
		placeholder: 'Add Option',
		default: {},
		displayOptions: show(['recordPayment']),
		options: paymentSourceOptions(),
	},

	{
		displayName: 'Status',
		name: 'status',
		type: 'options',
		options: [
			{ name: 'All', value: 'all' },
			{ name: 'Paid', value: 'paid' },
			{ name: 'Pending', value: 'pending' },
			{ name: 'Skipped', value: 'skipped' },
		],
		default: 'pending',
		displayOptions: show(['getAll']),
		routing: { send: { type: 'query', property: 'status' } },
	},
	{
		displayName: 'Filters',
		name: 'filters',
		type: 'collection',
		placeholder: 'Add Filter',
		default: {},
		displayOptions: show(['getAll']),
		options: [
			{
				displayName: 'Due From',
				name: 'from',
				type: 'dateTime',
				default: '',
				description: 'First due date to include',
				routing: { send: { type: 'query', property: 'from', value: toCalendarDate } },
			},
			{
				displayName: 'Due To',
				name: 'to',
				type: 'dateTime',
				default: '',
				description: 'Last due date to include',
				routing: { send: { type: 'query', property: 'to', value: toCalendarDate } },
			},
		],
	},
	...returnAllAndLimit(R, 'getAll'),
];
